package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.AssigneeVO;

@RequiredArgsConstructor
public class AssigneeValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<AssigneeVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param assignee
   * @return
   */
  public T assignee(AssigneeVO assignee) {
    this.value = Optional.of(assignee);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param assignee
   * @return
   */
  public T assignee(Optional<AssigneeVO> assignee) {
    this.value = assignee;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param assignee
   * @return
   */
  public T assignee(String assignee) {
    this.value = Optional.of(AssigneeVO.from(assignee));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T assigneeNull() {
    this.value = Optional.of(AssigneeVO.nullValue());
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getAssignee() {
    return value.flatMap(AssigneeVO::getAssignee);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<AssigneeVO> getAssigneeValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public AssigneeVO readAssignee(final Optional<ObservedIssue> original,
      final ConstraintFailList fails) {
    return value
        .orElse(original.map(ObservedIssue::getAssigneeValue).orElseGet(AssigneeVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetAssignee() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetAssigneeIfMatches(final String field) {
    if ("assignee".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
